import { useRuntimeConfig } from "#app";
import { IMPACT_COLORS } from "../constants.js";
export function createLogger() {
  function logViolation(violation) {
    const config = useRuntimeConfig();
    if (!config.public.a11yLogIssues) {
      return;
    }
    const impact = violation.impact ?? "moderate";
    const color = IMPACT_COLORS[impact];
    const isE2ETest = typeof navigator !== "undefined" && (navigator.webdriver === true || !!window.__playwright);
    const logData = isE2ETest ? violation.nodes.filter((i) => !i.target?.includes("html")).map((i) => i.html) : violation.nodes.filter((i) => !i.target?.includes("html") && i.element).map((i) => i.element);
    console[impact === "critical" ? "error" : "warn"](
      `%ca11y%c ${violation.help}
  ${violation.helpUrl}
`,
      `color: white; border-radius: 3px; padding: 2px 3px; font-size: 0.8em; background: ${color};`,
      "",
      ...logData
    );
  }
  return {
    logViolation
  };
}
